mapper.select:
SELECT cipher_name AS cipherName, is_accepted AS accepted, key_size AS keySize, forward_secrecy AS forwardSecrecy, openssl_name AS opensslName, CASE WHEN cipher_name LIKE '%_RC4_%' THEN '存在严重漏洞（如BEAST攻击），且易受时间旁路攻击，建议禁用RC4算法' WHEN cipher_name LIKE '%_DES_%' OR cipher_name LIKE '%_3DES_%' THEN '密钥长度不足，易被暴力破解，建议禁用DES/3DES算法' WHEN cipher_name LIKE '%_NULL_%' OR cipher_name LIKE '%_anon_%' OR cipher_name LIKE '%_ADH_%' THEN '不提供加密或缺乏身份验证，建议禁用含有NULL、anon或ADH的密码套件' WHEN cipher_name LIKE '%_CBC_%' THEN 'CBC模式已被TLS 1.3淘汰​，建议升级为​TLS 1.3 + AEAD​ 模式' WHEN cipher_name LIKE '%_DH_%' THEN '​DH静态密钥不支持前向加密，建议使用DHE并确保密钥≥2048位' ELSE '安全' END AS remark FROM cipher_suite_support LEFT JOIN scan_target starget ON cipher_suite_support.target_id = starget.target_id LEFT JOIN scan_task ON scan_task.task_id = starget.task_id WHERE scan_task.task_id = #{taskId}
AND starget.target_id = #{targetId}
AND cipher_suite_support.tls_version = #{tlsVersion}
AND starget.count = #{count}
LIMIT #{offset}, #{size};

SELECT COUNT(*) AS total_count
FROM (
SELECT cipher_name AS cipherName,
is_accepted AS accepted,
key_size AS keySize,
forward_secrecy AS forwardSecrecy,
openssl_name AS opensslName
FROM cipher_suite_support
LEFT JOIN scan_target starget ON cipher_suite_support.target_id = starget.target_id
LEFT JOIN scan_task ON scan_task.task_id = starget.task_id
WHERE scan_task.task_id = #{taskId}

    AND starget.target_id = #{targetId}


    AND cipher_suite_support.tls_version = #{tlsVersion}


    AND starget.count = #{count}

     ) AS subquery
